import itertools
import collections

def R_KKK(x, y, z, K):
    """
    Calculates R(K, K, K) for a given triplet (x, y, z) and parameter K.
    R(K, K, K) = |x+y-2K| + |y+z-2K| + |z+x-2K|
    """
    return abs(x + y - 2 * K) + abs(y + z - 2 * K) + abs(z + x - 2 * K)

def solve_ambiguity():
    # Map to store the vector V (tuple of 10 values) to a list of triplets (x, y, z)
    vector_to_triplets = collections.defaultdict(list)

    # Iterate through all 1000 possible triplets (x, y, z)
    triplets = list(itertools.product(range(10), repeat=3))

    print(f"Starting calculation for {len(triplets)} triplets...")

    for x, y, z in triplets:
        # Calculate the vector V = (R(0,0,0), R(1,1,1), ..., R(9,9,9))
        V = []
        for K in range(10):
            value = R_KKK(x, y, z, K)
            V.append(value)

        V_tuple = tuple(V)

        # Store the triplet corresponding to this vector
        vector_to_triplets[V_tuple].append((x, y, z))

    # Identify ambiguous pairs (vectors mapped to more than one triplet)
    ambiguous_vectors = {}
    for V_tuple, triplets_list in vector_to_triplets.items():
        if len(triplets_list) > 1:
            ambiguous_vectors[V_tuple] = triplets_list

    print("\n--- Results ---")
    if ambiguous_vectors:
        print(f"Found {len(ambiguous_vectors)} sets of ambiguous vectors.")
        for V, triplets in ambiguous_vectors.items():
            print(f"\nVector V: {V}")
            print("Ambiguous triplets:")
            for t in triplets:
                print(f"  {t}")
    else:
        print("No ambiguous triplets found. Each triplet has a unique 10-dimensional fingerprint V.")

solve_ambiguity()

